"""Run locally only. NEVER commit or share private key generated by this script."""
import base64
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import ec


def b64url(data):
    return base64.urlsafe_b64encode(data).decode('ascii').rstrip('=')

key = ec.generate_private_key(ec.SECP256R1())
private_der = key.private_bytes(
    encoding=serialization.Encoding.DER,
    format=serialization.PrivateFormat.TraditionalOpenSSL,
    encryption_algorithm=serialization.NoEncryption(),
)
public_bytes = key.public_key().public_bytes(
    encoding=serialization.Encoding.X962,
    format=serialization.PublicFormat.UncompressedPoint,
)
print('PUBLIC KEY - put in docs/push-config.json:')
print(b64url(public_bytes))
print('\nPRIVATE KEY - put ONLY in GitHub Actions secret PUSH_VAPID_PRIVATE_KEY:')
print(b64url(private_der))
print('\nDo not paste the private key in ChatGPT, source code, or public files.')
